@dataclass(frozen=True)
class CodingToolMode(NativeToolMode):
    owner: CodingToolOwner

    def launch_arguments(self, package: Path) -> tuple[str, ...]:
        extension = Path(package) / 'dist/channel_coding_tools.mjs'
        if not extension.is_file():
            raise SelectedToolDenied('Native coding extension is not installed')
        return ('--tools', ','.join(CodingTool.names()), '-e', str(extension))

    def socket(self, directory: Path, token: str) -> OwnerToolSocket:
        return CodingToolSocket(directory, token, self.owner)

    def finish(self) -> None:
        self.owner.finish()

@contextmanager
def _selected_claim_boundary(comms: Comms, store: Coordination, admission: WakeAdmission, owner_name: str):
    """One wire/bus/registry boundary for claim acquisition and exact release."""
    if type(comms) is not Comms or type(store) is not Coordination:
        raise TypeError('Wake claim requires the actual wire and coordinator stores')
    if type(admission) is not WakeAdmission or type(owner_name) is not str:
        raise IdentityConflict('Wake claim admission is not typed')
    if store.session.path.resolve() != (comms.root / 'coordination.sqlite3').resolve():
        raise IdentityConflict('Wake coordinator does not belong to this wire root')
    bus = comms.bus
    with _store_lock(comms._wire_lock_path), bus.log.locked(), _store_lock(comms.registry.store.path):
        registry = comms.registry.store._read_unlocked().snapshot()
        canonical = registry.aliases.get(owner_name, owner_name)
        try:
            captured = RegistryOwner.capture(registry, canonical, 'Selected wake owner stopped or changed')
            captured.require_active_turn()
        except StaleFence as error:
            raise IdentityConflict('Selected wake owner stopped or changed') from error
        owner, generation = (captured.thread, captured.admission_generation)
        _require_no_private_owner_rename(comms.root)
        metadata = bus.log._private_marker_unlocked()
        if metadata.root_id != admission.wire_root_id:
            raise IdentityConflict('Selected wake belongs to another wire root')
        if admission.source_seq <= metadata.admission_after_seq:
            raise IdentityConflict('Selected wake precedes the current admission floor')
        initial = next((row for record in bus.log.verified_records_unlocked(metadata) for row in record.deliveries() if row.message.seq == admission.source_seq), None)
        if initial is None:
            raise IdentityConflict('Selected wake has no committed initial row')
        with store.session.read():
            _verify_selected_wake_state(initial, owner, generation, store, admission)
            yield (bus, metadata, registry, owner, initial)

def release_selected_resources(comms: Comms, store: Coordination, admission: WakeAdmission, owner_name: str, claims: tuple[ClaimOwner, ...]) -> None:
    """Release only these observed generations under their current selected owner."""
    if not claims:
        return
    with _selected_claim_boundary(comms, store, admission, owner_name) as (bus, metadata, registry, owner, initial):
        projection, _ = bus.log._claim_projection_unlocked(metadata)
        if any((projection.get(assignment.resource) != assignment for assignment in claims)):
            raise IdentityConflict('Coding claim changed before release')
        target = initial.message.sender if initial.message.sender != owner.name else BuiltinChannel.ALL.value
        bus.publisher.publish_claim_envelope(Message(owner.name, target, 'Completed coding tool claims released', MessageType.INFO, notice=True), worktree=Path(owner.worktree), incarnation=str(owner.created_at), releases=tuple((assignment.resource for assignment in claims)), _locked_registry_snapshot=registry, _bus_locked=True)

class NativeToolMode(ABC):
    """Owner-bound native tool policy shared by selected and normal coding turns."""

    @abstractmethod
    def launch_arguments(self, package: Path) -> tuple[str, ...]:
        """Return the native tool selection and reviewed extension."""

    def finish(self) -> None:
        """Release completed coding claims; selected proof keeps its old semantics."""
        return None

    @abstractmethod
    def socket(self, directory: Path, token: str) -> OwnerToolSocket:
        """Create the existing authenticated owner transport for this policy."""
